INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-021', TRUE, '经济管理学院', '2026-04-03', '经济管理学院召开全体教职工大会本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期各项重点工", "quote": "本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期各项重点工"}]'::jsonb, '校内通知：经济管理学院召开全体教职工大会本网讯 4月1日下午，经济管理学院在经管楼411会', '[{"text": "本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期各项重点工", "quote": "本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期各项重点工"}]'::jsonb, '本网讯 4月1日下午，经济管理学院在经管楼411会议室召开全体教职工大会，全面部署学院近期各项重点工作，学院领导班子及全体教职工参加会议。 会议传达学习了校八届二次党代会暨2026年全面从严治党工作会议精神，强调要以树立和践行正确政绩观学习教育为重要契机，持续深化工作作风，扎实推进学院“十五五”规划编制及2026年度重点工作落地见效，以担当实干为学校“双一流”创建贡献经管智慧。同时，围绕研究生招生工作，明确要求始终坚持公平公正原则，严格规范工作流程，确保平稳有序完成本年度研究生招录任务。 会议结合近期教育系统典型案', 'https://jgxy.ahau.edu.cn/info/1101/23456.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at